&lt;p&gt;&lt;em&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;Musik ist deine Leidenschaft&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt; – nicht nur das Hören&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt; weckt dein Interesse, sondern auch die Prozesse&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;/Set-Ups dahinter? &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;Du arbeitest gerne mit &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;Systemen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;?&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;Man schätzt dich für deine präzise Arbeitsweise? &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;Du b&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;ist stark in der Kommunikation&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;ein absolutes Organisationstalent&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt; und behältst in jeder Situation den Überblick&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226026080 BCX0&quot;&gt;? Dann suchen wir dich.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Was du machst&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du bildest eine wichtige Schnittstelle zwischen unseren Labels, der Katalogabteilung und allen internen Abteilungen, die für die Veröffentlichung unserer Produkte zuständig sind und arbeitest eng mit PMM, CMM &amp;amp; Artist/Management sowie nat. und internationalen Repertoiregebern zusammen&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du steuerst den gesamten Produktentwicklungsprozesses gemeinsam mit weiteren internen Schnittstellen von der Anlage über Scheduling bis hin zur Auslieferung bei den DSPs – von A wie Apple Music bis Y wie Youtube&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du überwachst die Einhaltung relevanter Timelines &amp;amp; Deadlines und sorgst für die Umsetzung von sinnvollen und technisch einwandfreien digitalen sowie physischen Produkt-Set-Ups &lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559737&amp;quot;:433,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du unterstützt beim Release Planning in Zusammenarbeit mit PMM, CMM &amp;amp; Artist/Management&amp;nbsp;&lt;span data-contrast=&quot;auto&quot;&gt;sowie nat. und internationalen Repertoiregebern&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Deine Kreativität ist bei der Erarbeitung physischer Produktkonfigurationen gefragt ebenso wie deine Expertise zur Einschätzung des D2C Set-Ups gemeinsam mit den Fachexpert*innen&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du koordinierst mit weiteren Fachexpert:innen das physische Produkt Set-Up inkl. aller damit zusammenhängenden Aufgaben&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du sorgts für eine klare Koordination &amp;amp; Administration von Künstler:innen- &amp;amp; Katalogprojekten in den internen Systemen – sowohl beim On- als auch beim Offboarding als auch bei Repertoireübernahmen und -abgaben&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du hilfts dabei, dass unsere Produkte chartfähig und GFK-gemeldet sind&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Du pflegst den Release-Plan deiner Abteilung&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559737&amp;quot;:433,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
