&lt;li style=&quot;line-height: 1.5;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;29&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;span class=&quot;TextRun SCXW13581749 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW13581749 BCX8&quot;&gt;You will have&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW13581749 BCX8&quot;&gt;ability&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW13581749 BCX8&quot;&gt;&amp;nbsp;to quickly learn new concepts and apply them in a consulting context.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW13581749 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 1.5;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;29&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;span class=&quot;TextRun SCXW117431713 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW117431713 BCX8&quot;&gt;You will have excellent communication and stakeholder management skills.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;span class=&quot;EOP Selected SCXW117431713 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;What a career at Baringa will give you&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;h3&gt;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;Putting&lt;/span&gt; &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span style=&quot;color: rgb(208, 0, 111);&quot;&gt;People&lt;/span&gt; &lt;/span&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;First.&lt;/span&gt; &lt;/span&gt;&lt;/h3&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Baringa is a People First company and wellbeing is at the forefront of our culture. We recognise the importance of work-life balance and flexible working and provide our staff amazing benefits. Some of these benefits include:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Generous Annual Leave Policy:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We recognise everyone needs a well-deserved break. We provide our employees with 5 weeks of annual leave, fully available at the start of each year. In addition to this, we have introduced our 5-Year Recharge benefit which allows all employees an additional 2 weeks of paid leave after 5 years continuous service.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Flexible Working:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We know that the ‘ideal’ work-life balance will vary from person to person and change at different stages of our working lives. To accommodate this, we have implemented a hybrid working policy and introduced more flexibility around taking unpaid leave.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Corporate Responsibility Days:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; Our world is important to us, so all our employees get 3 every year to help social and environmental causes and increase our impact on the communities that mean the most to us.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Wellbeing Fund:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We want to encourage all employees to take charge and prioritise their own wellbeing. We’ve introduced our annual People Fund to support this by offering every individual a fund to support and manage their wellbeing through an activity of their choice.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Profit Share Scheme:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; All employees participate in the Baringa Group Profit Share Scheme so everyone has a stake in the company’s success.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot; data-contrast=&quot;none&quot;&gt;Diversity and Inclusion&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We are proud to be an Equal Opportunity Employer. We believe that creating an environment where everyone feels a sense of belonging is central to our culture and that diversity is paramount to driving creativity, innovation, and value for our clients and for our people.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot; data-contrast=&quot;none&quot;&gt;An award-winning workplace&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;You can be a part of our ‘Great Place to Work’ – with our commitment to women and well-being in the workplace for all. &lt;/span&gt;&lt;a href=&quot;https://www.baringa.com/en/impact/awards/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Click here&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt; to see some of our recent awards and how we’ve achieved this.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Using business as a force for good.&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We maintain high standards of environmental performance and transparency, which can be seen through our commitment to Net Zero with our SBTI-verified Scope 1, 2 and 3 emissions reduction targets and our support of the Better Business Act. We report our progress publicly and ensure that we are also externally assessed and scored through organisations like CDP and EcoVadis - helping us to continually identify where we can improve.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We have a long legacy of supporting the communities in which we work, and offer a variety of ways to contribute, by putting people first and creating impact that lasts. Our Corporate Social Responsibility (CSR) agenda is about giving back to the communities in which we live and work by sharing our skills, talent and time. In essence, we aim to empower and encourage everyone in the firm to contribute to the things we care about, and support registered charities and organisations with a clear social or environmental purpose to increase the positive impact they can have.&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;&lt;span style=&quot;color: rgb(208, 0, 111); font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;Join us&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;All applications received will be reviewed by a member of our Talent Acquisition team. We never rely solely on automated screening or AI tools to make hiring decisions. Your application will be considered for employment without regard to race, ethnicity, religion, gender, gender identity or expression, sexual orientation, nationality, disability, age, faith or social background. We do not filter applications by university background and encourage those who have taken alternative educational and career paths to apply. We would like to actively encourage applications from those who identify with less represented and minority groups. We operate an inclusive recruitment process, ensuring reasonable adjustments where needed. Please contact a member of our Recruitment Team to discuss further.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(208, 0, 111); font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;Baringa Privacy Notices&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For UK &amp;amp; EU&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data will be retained by Baringa for up to two years, in accordance with our &lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-004-ukrpn---uk-recruitment-privacy-notice-pdf.pdf&quot;&gt;UK Recruitment Privacy Notice / &lt;/a&gt;&lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-005-eurpn---eu-recruitment-privacy-notice-pdf.pdf&quot;&gt;EU Recruitment Privacy Notice&lt;/a&gt;, to evaluate your application and meet our legal and reporting obligations. In line with the General Data Protection Regulation (GDPR), you have the right to request access to, rectification, or erasure (subject to legal limitations) of your personal data. For more information, please contact us at &lt;a ----------
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For the USA&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data may be retained by Baringa for up to two years, as outlined in our&amp;nbsp;&lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-007-nerpn-amer--apac-recruitment-privacy-notice-word.pdf&quot;&gt;Recruitment Privacy Notice (AMER &amp;amp; APAC)&lt;/a&gt;, to support the recruitment process and internal reporting requirements. Where applicable, and in accordance with relevant federal and state laws, you may have the right to request access to or correction of your personal information. For further details, please contact &lt;a ----------
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For Australia &amp;amp; Singapore&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data will be retained by Baringa for up to two years, in accordance with our &lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-007-nerpn-amer--apac-recruitment-privacy-notice-word.pdf&quot;&gt;Recruitment Privacy Notice (AMER &amp;amp; APAC)&lt;/a&gt;, to assess your application and meet applicable reporting and legal obligations. In line with the Australian Privacy Act and Singapore’s Personal Data Protection Act (PDPA), you may have rights to access, correct, or request limited deletion of your personal data. For more information, please contact us at &lt;a ----------<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;ms-outlook-mobile-reference-message skipProofing&quot;&gt;&lt;strong&gt;About WPP Production&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message skipProofing&quot;&gt;We are WPP Production - the unified global production company that brings together all of WPP&#39;s content producers, studios and craft experts into one connected organisation. We combine world-class human craft with next generation technology to originate, design, and deliver multi-channel content systems at scale. Built for borderless collaboration and powered by deep craft expertise, we are the production engine designed for today&#39;s always on, AI driven marketing world.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About WPP&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;WPP is the trusted growth partner for the world’s leading brands. We unite&amp;nbsp;cutting-edge media intelligence and data solutions, world-class creativity, next-generation production, transformative enterprise solutions and expert strategic counsel&amp;nbsp;in a single company –&amp;nbsp;powered by exceptional talent and our agentic marketing platform, WPP Open,&amp;nbsp;to help our clients navigate change, capture opportunity and deliver transformational growth. For more information, visit&amp;nbsp;&lt;a href=&quot;https://urldefense.com/v3/__http://wpp.com/__;!!JboVxjCXSME!N9KGoZIn5nCC-uOWhEdE-ChrrJuf6TgkLzNNkLaW9BExJsVqZZ_hMSmGbARJ0tdBOnKYM7kEbv5L3ncUpg7-6uEPNdY$&quot; data-outlook-id=&quot;6ded86b6-cde3-4e48-958d-34727f881edd&quot;&gt;WPP.com&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;A Hybrid working model&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;p class=&quot;xmsonormal&quot;&gt;&lt;em&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;What does the &lt;strong&gt;New Business Director (Global)&amp;nbsp; &lt;/strong&gt;do a WPP Production?&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The New Business Director plays a pivotal role in shaping and driving growth for WPP Production, defining how we win high-value, complex opportunities and shaping the strategic direction of our growth function.&lt;/p&gt;
&lt;p&gt;This is a highly strategic role, responsible for designing integrated solutions, evolving go-to-market propositions and building a repeatable growth engine that enables the business to win consistently across markets and opportunity types.&lt;/p&gt;
&lt;p&gt;You will lead the strategic direction and narrative for priority opportunities — ensuring that every response is clearly positioned, commercially compelling and aligned to client needs. You will be accountable for the quality and consistency of our narrative and strategic output across all pitches, setting the standard for how we articulate our value.&lt;/p&gt;
&lt;p&gt;Working closely with senior stakeholders across WPP Production and the wider WPP network, you will play a key role in driving integration across Media, Creative and Production, shaping how we bring together capabilities to deliver differentiated client solutions.&lt;/p&gt;
&lt;p&gt;Beyond individual opportunities, you will take a broader view of growth — defining where we should focus, how we prioritise opportunities, and how we scale success globally. This includes evolving our approach to pitches, refining commercial models and embedding best practice ways of working across the team.&lt;/p&gt;
&lt;p&gt;This is a high-impact role with visibility across the business, suited to someone who thrives in complexity, operates with a high level of autonomy, and is motivated by driving measurable growth and business impact at scale.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key areas of responsibility&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Define and lead the strategic direction for priority, high-value opportunities, ensuring a clear and differentiated approach to winning&lt;/li&gt;
&lt;li&gt;Accountable for the narrative quality and strategic standard across all pitches, setting the benchmark for how we articulate our value&lt;/li&gt;
&lt;li&gt;Design end-to-end client solutions and commercial models, including operating models, pricing approach and value proposition&lt;/li&gt;
&lt;li&gt;Lead the development of go-to-market propositions, continuously evolving how WPP Production positions itself in market&lt;/li&gt;
&lt;li&gt;Work with the Global Chief Growth Officer to define and drive the global growth strategy for WPP Production, identifying priority markets, opportunity types and areas of focus&lt;/li&gt;
&lt;li&gt;Define and influence where we focus our growth efforts, ensuring time and resource are prioritised on the highest value opportunities&lt;/li&gt;
&lt;li&gt;Analyse pipeline, performance and market trends to identify where growth is coming from — and where it should come from next&lt;/li&gt;
&lt;li&gt;Partner with senior leadership to shape growth priorities, targets and investment decisions&lt;/li&gt;
&lt;li&gt;Drive improved conversion, efficiency and revenue impact across the new business pipeline through stronger strategic positioning and approach&lt;/li&gt;
&lt;li&gt;Build and scale a repeatable growth engine, embedding frameworks, playbooks, tools and best practice that enable teams globally to win consistently without central dependency&lt;/li&gt;
&lt;li&gt;Act as a “pitch doctor”, stepping into critical opportunities to strengthen narrative, structure and overall response quality&lt;/li&gt;
&lt;li&gt;Present and represent WPP Production in senior client meetings &amp;amp; pitch meetings&lt;/li&gt;
&lt;li&gt;Drive cross-WPP integration, ensuring seamless collaboration across Media, Creative and Production&lt;/li&gt;
&lt;li&gt;Identify and embed new ways of working, improving how we approach, structure and deliver pitches&lt;/li&gt;
&lt;li&gt;Lead on innovation in growth, including exploring the use of AI and new technologies to enhance team capability and efficiency&lt;/li&gt;
&lt;li&gt;Build and maintain strong relationships with senior stakeholders across WPP and key client organisations&lt;/li&gt;
&lt;li&gt;Develop and scale team capability, through coaching, mentoring and training&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What good looks like (key requirements)&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Significant experience (typically 10+ years) in new business, growth or strategy roles within a creative, production or agency environment&lt;/li&gt;
&lt;li&gt;Exceptional strategic thinking, with a proven ability to define how complex opportunities are approached and won&lt;/li&gt;
&lt;li&gt;Outstanding writing and storytelling ability, with experience leading narrative development for high-value, multi-disciplinary pitches&lt;/li&gt;
&lt;li&gt;Strong commercial acumen, with experience designing and influencing commercial models, pricing strategies and value propositions&lt;/li&gt;
&lt;li&gt;Proven experience leading large, complex and high-value pitch processes, often involving multiple stakeholders and disciplines&lt;/li&gt;
&lt;li&gt;Confident and credible communicator, with experience presenting to senior clients and influencing at leadership level&lt;/li&gt;
&lt;li&gt;Comfortable operating at pace and under pressure, managing multiple high-stakes opportunities simultaneously&lt;/li&gt;
&lt;li&gt;Strong understanding of integrated marketing ecosystems, including the intersection of media, creative and production&lt;/li&gt;
&lt;li&gt;Able to influence and align senior stakeholders, often with competing priorities, to a single direction&lt;/li&gt;
&lt;li&gt;Experience shaping or evolving go-to-market propositions and strategic positioning&lt;/li&gt;
&lt;li&gt;Ability to operate effectively in ambiguous, fast-paced environments, bringing structure and clarity to complex challenges&lt;/li&gt;
&lt;li&gt;A proactive and solutions-driven mindset, with a strong sense of ownership and accountability&lt;/li&gt;
&lt;li&gt;Experience developing and mentoring team members, with a focus on building capability and scaling impact&lt;/li&gt;
&lt;li&gt;Curious and forward-thinking, with an interest in innovation, AI and the future of content and production&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;#LI-HYBRID&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;#LI-RH1&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Why work here:&amp;nbsp;&lt;br&gt;&lt;/strong&gt;&lt;span data-teams=&quot;true&quot;&gt;At WPP Production, you’ll help shape the future of content production at a truly global scale. We bring together world-class talent, cutting-edge studios, and advanced technology to solve some of the most complex creative and production challenges in the industry. You’ll work in a collaborative, borderless environment where craft excellence is valued, innovation is encouraged, and AI and next-generation tools are used to amplify not replace human creativity. With access to diverse projects, global career opportunities, and the backing of WPP’s unmatched network, this is a place where you can grow your skills, make real impact, and create work that performs for every audience, across every channel, at every moment. &lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Inclusion and Impact&amp;nbsp;&lt;/strong&gt;&lt;br&gt;WPP is an equal opportunity employer and considers applicants for all positions without discrimination or regard to particular characteristics. We are committed to fostering a culture of respect in which everyone feels they belong and has the same opportunities to progress in their careers. &lt;br&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;Data&lt;/strong&gt;&lt;br&gt;We rely on legitimate interest as a legal basis for processing personal information under the GDPR for purposes of recruitment and applications for employment. When you click the &quot;Submit Application&quot; button at the bottom of this page, this will send all the information you have added to WPP Production. Before you do this, we think it&#39;s a good idea to read through our Privacy&amp;nbsp;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;a href=&quot;https://www.hogarthww.com/privacy-policy&quot;&gt;st&lt;/a&gt;&lt;a href=&quot;https://www.hogarth.com/privacy-policy&quot;&gt;atement&lt;/a&gt;.&lt;/span&gt; This explains what we do with your personal data when you apply for a role with us, and, how you can update the information you have provided us with or how to remove it.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;
&lt;p class=&quot;xmsonormal&quot; style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Please contact &lt;a ----- ----- if you need the job advert or form in another format.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Anduril Industries is a defense technology company with a mission to transform U.S. and allied military capabilities with advanced technology. By bringing the expertise, technology, and business model of the 21st century’s most innovative companies to the defense industry, Anduril is changing how military systems are designed, built and sold. Anduril’s family of systems is powered by Lattice OS, an AI-powered operating system that turns thousands of data streams into a realtime, 3D command and control center. As the world enters an era of strategic competition, Anduril is committed to bringing cutting-edge autonomy, AI, computer vision, sensor fusion, and networking technology to the military in months, not years.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;ABOUT THE TEAM&lt;/h3&gt;
&lt;p&gt;Anduril is the world&#39;s fastest-growing defence technology company, bringing commercial technology talent and venture funding to the defence and security sectors. Our technology helps Australia, the United States, and allied nations solve their hardest national security challenges by enabling operators to make better, more informed decisions in life-and-death situations. We have assembled a diverse team of experts in artificial intelligence, computer vision, sensor fusion, optics, and data analysis that are creating software and hardware solutions to radically evolve the capabilities of Australia, the United States, our allies, and commercial customers. If you are passionate about solving problems that have a real impact, come join Anduril and build the future of defence.&lt;br&gt;&lt;br&gt;A critical part of the Anduril team is its Contracts Managers, who play a crucial role in program success. They interface daily with a motivated team of program leadership, functional leadership, and customers in fast-paced environments. &lt;/p&gt;
&lt;h3&gt;ABOUT THE JOB&lt;/h3&gt;
&lt;p&gt;Anduril is seeking a talented Contracts Manager to support a variety of Government, International, and Commercial contracts and programs. In this role, you will oversee the full contract lifecycle for Anduril&#39;s government and commercial contracts, ensuring compliance, minimizing risk, and optimizing contract performance. The ideal candidate will combine deep knowledge of commercial and defence contracting with strong negotiation skills and a passion for supporting national security through technological innovation. &lt;br&gt;&lt;br&gt;The position will be responsible for providing contract support for various Government contracts and commercial contracts. Support of these contracts will involve proposal support, contract negotiation, contract compliance, contract management, contract modifications, and contract close-out. This role works closely with the legal and proposal teams as well as across the spectrum of Anduril’s accounting, business operations, program, and engineering teams.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;h4&gt;WHAT YOU WILL DO&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Execute contract management throughout the life of each contract.&lt;/li&gt;
&lt;li&gt;Complete contract review and acceptance.&lt;/li&gt;
&lt;li&gt;Oversee and prepare contract proposal planning and management and support preparation of proposals.&lt;/li&gt;
&lt;li&gt;Ensure compliance with government regulations, legal requirements, and company policies.&lt;/li&gt;
&lt;li&gt;Assist in identification, development, and implementation of new contract policies and processes.&lt;/li&gt;
&lt;li&gt;Maintain comprehensive contract documentation and compliance records.&lt;/li&gt;
&lt;li&gt;Provide contract summaries and ensure contract execution in accordance with government and company requirements.&lt;/li&gt;
&lt;li&gt;Provide program managers and executives with contract briefs during the life of contracts.&lt;/li&gt;
&lt;li&gt;Provide guidance on ASDEFCON requirements and other regulatory considerations.&lt;/li&gt;
&lt;li&gt;Cultivate strong, ongoing relationships with internal/external customers.&lt;/li&gt;
&lt;li&gt;Provide contractual guidance and risk mitigation strategies for contractual and business obligations.&lt;/li&gt;
&lt;li&gt;Negotiate complex contractual terms with government agencies, prime contractors, and subcontractors.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;REQUIRED QUALIFICATIONS&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;6+ years of relevant contract management experience.&lt;/li&gt;
&lt;li&gt;Bachelor’s Degree in business administration, government, or a related field.&lt;/li&gt;
&lt;li&gt;A strong working knowledge of Australian Government contracting including ASDEFCON, Commonwealth Procurement Rules (CPRs), and/or Defence Security Principles Framework (DSPF) experience.&lt;/li&gt;
&lt;li&gt;Experience with full life cycle contract management for various types of contract agreements&lt;/li&gt;
&lt;li&gt;Excellent verbal and written communication skills&lt;/li&gt;
&lt;li&gt;Exceptional analytical and problem-solving abilities. You are highly respected amongst your peers and/or counterparts and known as someone who gets things done.&lt;/li&gt;
&lt;li&gt;Australian citizenship and ability to obtain and maintain an NV1 security clearance.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h4&gt;PREFERRED QUALIFICATIONS&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Direct experience working for or with major Australian defence primes&lt;/li&gt;
&lt;li&gt;IACCM/World Commerce &amp;amp; Contracting certification, Certified Professional Contracts Manager (CPCM), or similar professional credentials&lt;/li&gt;
&lt;li&gt;Graduate degree in business, law, government, or a related field.&lt;/li&gt;
&lt;li&gt;Knowledge of AUKUS initiatives and Australia-US-UK defence collaboration framework&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The salary range for this role is an estimate based on a wide range of compensation factors, inclusive of base salary only. Actual salary offer may vary based on (but not limited to) work experience, education and/or training, critical skills, and/or business considerations. Highly competitive equity grants are included in the majority of full time offers; and are considered part of Anduril&#39;s total compensation package. Additionally, Anduril offers top-tier benefits for full-time employees, including:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3 class=&quot;detailElios&quot;&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Anduril, we invest in our people. Our comprehensive, competitive benefits package (available at little to no cost to employees) ensures you’re supported in health, recovery, and whatever comes next.&amp;nbsp;&lt;/span&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For more information, &lt;a href=&quot;https://www.anduril.com/careers&quot;&gt;Explore Our Benefits&lt;/a&gt;.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;RichText column1&quot;&gt;
&lt;h3 class=&quot;detailElios&quot;&gt;&lt;strong&gt;Protecting Yourself from Recruitment Scams&lt;/strong&gt;&lt;/h3&gt;
&lt;p class=&quot;detailElios&quot;&gt;Anduril is committed to maintaining the integrity of our Talent acquisition process and the security of our candidates. We&#39;ve observed a rise in sophisticated phishing and fraudulent schemes where individuals impersonate Anduril representatives, luring job seekers with false interviews or job offers. These scammers often attempt to extract payment or sensitive personal information.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;RichText column2&quot;&gt;
&lt;p class=&quot;detailElios&quot;&gt;To ensure your safety and help you navigate your job search with confidence, please keep the following critical points in mind:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p class=&quot;detailElios&quot;&gt;&lt;strong&gt;No Financial Requests:&amp;nbsp;&lt;/strong&gt;Anduril will never solicit payment or demand personal financial details (such as banking information, credit card numbers, or social security numbers) at any stage of our hiring process. Our legitimate recruitment is entirely free for candidates.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Please always verify communications:&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;Direct from Anduril: If you receive an email from one of our recruiters, it will &lt;em&gt;only&lt;/em&gt; come from an ----- address.&lt;/li&gt;
&lt;li&gt;Via Agency Partner: If contacted by a recruiting agency for an Anduril role, their email will clearly identify their agency. If you suspect any suspicious activity, please verify the agency&#39;s authenticity by reaching out to &lt;a ----------
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p class=&quot;detailElios&quot;&gt;&lt;strong&gt;Exercise Caution with Unsolicited Outreach:&lt;/strong&gt;&amp;nbsp;If you receive any communication that appears suspicious, contains grammatical errors, or makes unusual requests, do not engage. Always confirm the sender&#39;s email domain is ----- before providing any personal information or clicking on links.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p class=&quot;detailElios&quot;&gt;&lt;strong&gt;What to Do If You Suspect Fraud:&lt;/strong&gt;&amp;nbsp;Should you encounter any questionable or fraudulent outreach claiming to be from Anduril, please report it immediately to&amp;nbsp;&lt;a ---------- Your proactive caution is invaluable in protecting your personal information and upholding the security and trustworthiness of our recruitment efforts.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;h3&gt;&lt;strong&gt;Data Privacy&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;To view Anduril&#39;s candidate data privacy policy, please visit &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&lt;a href=&quot;https://anduril.com/applicant-privacy-notice/&quot;&gt;https://anduril.com/applicant-privacy-notice/&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;By submitting your application, you consent to Anduril Industries using a third-party service provider to conduct pre-employment risk, integrity, and due diligence screening and assessing potential risks as part of your application process. This third-party service provider provides risk-intelligence services that may include analysis of sanctions and watchlists, adverse media, public-record information, and other lawful open-source or commercial data sources. This third-party service provider does not act as a consumer reporting agency. Use of this provider helps to ensure compliance with applicable laws and protect technology, intellectual property, and organizational security.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;div&gt;
&lt;div&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;color: #072b55;&quot;&gt;About Boomi and What Makes Us Special&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;p&gt;&lt;span style=&quot;color: #072b55;&quot;&gt;Are you ready to work at a fast-growing company where you can make a difference?&amp;nbsp;Boomi, the data activation company for AI, powers the agentic enterprise by bringing data to life across the business. The award-winning&amp;nbsp;Boomi Enterprise Platform is the active data foundation that delivers essential agentic infrastructure enabling organizations to drive agentic transformation and&amp;nbsp;harness the power of AI with secure, scalable connectivity.&amp;nbsp;&amp;nbsp;Trusted by over 30,000 customers and supported by a network of 800+ partners, Boomi helps organisations of all sizes achieve agility, efficiency, and innovation at scale.&amp;nbsp;At Boomi, you’ll work with world-class people and industry-leading technology. We hire trailblazers with an entrepreneurial spirit who can solve challenging problems, make a real impact, and want to be part of building something big. If this sounds like a good fit for you, check out&amp;nbsp;&lt;a href=&quot;http://www.boomi.com/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=http://www.boomi.com/&amp;amp;source=gmail&amp;amp;ust=1782843859988000&amp;amp;usg=AOvVaw3Yitd6hYQcya0j0B5k0__J&quot;&gt;boomi.com&lt;/a&gt;&amp;nbsp; or visit our&amp;nbsp;&lt;a href=&quot;https://boomi.com/company/careers/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://boomi.com/company/careers/&amp;amp;source=gmail&amp;amp;ust=1782843859988000&amp;amp;usg=AOvVaw2W_0H5BboonDUat_xHGW0d&quot;&gt;Boomi Careers&lt;/a&gt;&amp;nbsp;page to learn more.&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;b&gt;About the Role&lt;/b&gt;&lt;/span&gt;&lt;p&gt;&lt;span style=&quot;color:#000000&quot;&gt;Are you a driven, results-oriented sales professional who thrives on building new business from the ground up? As an &lt;b&gt;Enterprise Account Executive for the UKI region&lt;/b&gt;, you will play a pivotal role in &lt;b&gt;driving net-new revenue growth&lt;/b&gt;, identifying and acquiring new customers, and expanding our presence in the market.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;color:#000000&quot;&gt;This is a high-impact, new business-focused role where you’ll develop and execute strategic sales plans to win new enterprise customers, leveraging our market-leading SaaS solutions. You’ll engage with senior decision-makers, articulate our value proposition, and close high-value deals in a fast-paced, competitive environment.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;color:#000000&quot;&gt;This position is remote, with a preference for candidates near London due to customer engagement opportunities.&lt;/span&gt;&lt;/p&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;b&gt;Key Responsibilities&lt;/b&gt;&lt;/span&gt;&lt;ul&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Develop and execute a new business sales strategy within the UKI region.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Own and exceed a quota focused on new customer acquisition.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Identify, engage, and convert new enterprise prospects through strategic prospecting, networking, and relationship-building.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Act as a trusted advisor, deeply understanding potential customers’ business challenges and aligning our solutions to their needs.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Lead the full sales cycle from lead generation to contract negotiation and closure.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Partner with internal teams, including marketing and pre-sales, to drive high-quality pipeline generation.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Develop joint go-to-market strategies with partners to unlock new opportunities.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Represent the company at industry events, conferences, and networking opportunities to expand market reach.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;/ul&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;b&gt;What We’re Looking For&lt;/b&gt;&lt;/span&gt;&lt;ul&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Proven success in enterprise SaaS sales, with a strong focus on new logo acquisition.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Many years of enterprise software field sales experience, ideally in data integration, data management, AI or a related technology domain.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Strong track record of hunting, closing new business, and exceeding quota in enterprise sales.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Ability to engage and influence C-level executives and key decision-makers.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Experience with complex, consultative sales cycles and selling technical platform solutions.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Proficiency in Salesforce, Clari, and MEDDPICC methodology.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Passionate about winning new business—a true sales hunter!&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;&lt;/ul&gt;&lt;p&gt;&lt;span style=&quot;color:#000000&quot;&gt;If you are a highly motivated, strategic sales professional who thrives on winning new business and making an impact, we’d love to hear from you today!&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;{please enter job description here}&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400; color: #072b55;&quot;&gt;&lt;strong&gt;Be Bold. Be You. Be Boomi.&lt;/strong&gt; We take pride in our culture and core values and are committed to being a place where everyone can be their true, authentic self. Our team members are our most valuable resources, and we look for and encourage diversity in backgrounds, thoughts, life experiences, knowledge, and capabilities.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400; color: #072b55;&quot;&gt;&lt;em&gt;Boomi strives to create an inclusive and accessible environment for candidates and employees. &lt;/em&gt;All employment decisions are based on business needs, job requirements, and individual qualifications.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;div&gt;&lt;strong&gt;What We’re Building&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;Honeycomb is a service for the near and present future, defining observability and raising expectations of what developer tools can do! We’re working with well known companies like HelloFresh, Slack, LaunchDarkly, and Vanguard and more across a range of industries. This is an exciting time in our trajectory, we’ve closed Series D funding, scaled past the 200-person mark, and were named to Forbes’ America’s Best Startups of 2022 and 2023!&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;If you want to see what we’ve been up to, please check out these &lt;a href=&quot;https://www.honeycomb.io/blog&quot; target=&quot;_blank&quot;&gt;blog posts&lt;/a&gt; and Honeycomb.io &lt;a href=&quot;https://www.honeycomb.io/category/press-releases&quot; target=&quot;_blank&quot;&gt;press releases&lt;/a&gt;.&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We come for the impact, and stay for the culture! We’re a talented, opinionated, passionate, fiercely inclusive, and responsible group of bees. We have conviction and we strive to live&amp;nbsp;&lt;a class=&quot;postings-link&quot; href=&quot;https://www.honeycomb.io/about/&quot; target=&quot;_blank&quot;&gt;&lt;u&gt;our values&lt;/u&gt;&lt;/a&gt;&amp;nbsp;every day. We want our people to do what they truly love amongst a team of highly talented (but humble) peers.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;How We Work&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We are a fully distributed company, which means we believe it is not where you sit, but how you deliver that matters most. We invest in our people and care about how you orient to our culture and processes. At the same time we imbue a lot of trust, autonomy, and accountability from Day 1. #LI-Remote&lt;/div&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Little more about the team:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You’ll join a high-performing, strategic sales team focused on moving Honeycomb further into the enterprise space. We’ve proven product-market fit, closed Fortune 500 logos, and built a pipeline that’s primed for the kind of enterprise sellers who know how to multi-thread, influence the C-suite, and navigate $500K–$1M+ ACV opportunities. This is not a role for a former mid-market rep trying to stretch—it’s built for enterprise closers who know the game and want to win it.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do in the role:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own and drive complex, 6–12+ month sales cycles with Fortune 1000 and Global 2000 companies&lt;/li&gt;
&lt;li&gt;Build strategic, multi-threaded relationships across engineering, DevOps, observability, and procurement leadership&lt;/li&gt;
&lt;li&gt;Sell consultatively, bringing deep understanding of the customer’s business, technical landscape, and buying process&lt;/li&gt;
&lt;li&gt;Collaborate cross-functionally with Solutions Architects, Product, and Customer Success to shape high-value, tailored deals&lt;/li&gt;
&lt;li&gt;Deliver predictable pipeline growth, accurate forecasting, and exceed quota targets&lt;/li&gt;
&lt;li&gt;Represent Honeycomb at key industry events, conferences, and executive briefings&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you’ll bring to the role:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;7+ years of full-cycle enterprise SaaS selling experience, ideally in DevOps, observability, or cloud infrastructure&lt;/li&gt;
&lt;li&gt;Proven ability to land $500K+ multi-year deals with complex buying committees&lt;/li&gt;
&lt;li&gt;Strong executive presence with the ability to influence C-level stakeholders across technical and non-technical roles&lt;/li&gt;
&lt;li&gt;Deep discovery, storytelling, and consultative selling expertise&lt;/li&gt;
&lt;li&gt;A track record of building champions and navigating enterprise buying cycles with precision&lt;/li&gt;
&lt;li&gt;Grit, ambition, and a bias for execution—someone who thrives in fast-paced, high-ownership environments&lt;/li&gt;
&lt;li&gt;Experience leveraging MEDDPICC, Command of the Message, or similar enterprise sales frameworks&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;On Target Earnings (OTE) based on level of experience (Base + Commission)&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;£220,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;£260,000 GBP&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;
&lt;p&gt;&lt;strong&gt;What you&#39;ll get when you join the Hive:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A stake in our success - generous equity with employee-friendly stock program&lt;/li&gt;
&lt;li&gt;It’s not about how strong of a negotiator you are - our pay is based on transparent levels relative to experience&lt;/li&gt;
&lt;li&gt;Time to recharge with unlimited PTO&lt;/li&gt;
&lt;li&gt;A distributed-first mindset and culture (really!)&lt;/li&gt;
&lt;li&gt;Home office, co-working, and internet stipend&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;1&quot;&gt;Full benefits coverage for employees, with additional coverage available for dependents&lt;/li&gt;
&lt;li&gt;Up to 16 weeks of paid parental leave, regardless of path to parenthood&lt;/li&gt;
&lt;li&gt;Annual development allowance&amp;nbsp;&lt;/li&gt;
&lt;li&gt;And much more...&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Please note we cannot currently sponsor or support visa transfers at this time. &lt;/strong&gt;Additionally, in compliance with applicable law, all persons hired will be required to verify identity and eligibility to work.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Phishing and Recruitment Scam Warning:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We take your security seriously. Please be aware that recruitment scams are increasingly common and scammers may create email addresses or websites to impersonate Honeycomb employees. To help protect you:&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;All communications will come from an ----- email address
&lt;ul&gt;
&lt;li&gt;We occasionally work with external recruiting agencies. These partners will use legitimate business email addresses—&lt;strong data-start=&quot;512&quot; data-end=&quot;559&quot;&gt;never personal accounts like Gmail or Yahoo&lt;/strong&gt;.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;Our recruiting process will &lt;strong data-start=&quot;592&quot; data-end=&quot;601&quot;&gt;never&lt;/strong&gt; ask you to provide financial or sensitive personal information, including but not limited to:
&lt;ul&gt;
&lt;li&gt;Social security or tax identification numbers&lt;/li&gt;
&lt;li&gt;Credit card numbers&lt;/li&gt;
&lt;li&gt;Bank account information&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Diversity &amp;amp; Accommodations:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We&#39;re committed to building a diverse, inclusive, and equitable workplace—where people of all backgrounds, identities, experiences, and abilities are welcomed, valued, and supported. We recognize that there is no single path to success and embrace nontraditional career journeys and diverse perspectives as key to building stronger, more innovative teams.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We strive to ensure an inclusive experience throughout every stage of our hiring process and are happy to provide reasonable accommodations as needed. If you require accommodations or accessible formats at any point during our hiring process, please let your recruiter know.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;As an equal opportunity employer our hiring process is designed to put you at ease and help you show your best work. If there’s anything we can do to improve your experience, we’re always open to feedback.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Privacy Notice:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;If you apply for a job at Honeycomb and your application is unsuccessful (or you withdraw from the process or decline our offer), Honeycomb will retain your information after your application for a period of time in accordance with local laws. We retain this information for various reasons, including in case we face a legal challenge in respect of a recruitment decision, to consider you for other current or future jobs at Honeycomb, and to help us better understand, analyze and improve our recruitment processes.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;For more information regarding our privacy practices please see the&amp;nbsp;&lt;a href=&quot;https://www.honeycomb.io/privacy&quot; target=&quot;_blank&quot;&gt;Honeycomb Privacy Notice&lt;/a&gt;.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;If you do not want us to retain your information, or want us to update it, please contact&amp;nbsp;&lt;a ----- ----- Please note, however, that we may retain some information if required by law or as necessary to protect ourselves from legal claims.&amp;nbsp;&lt;/div&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p&gt;(FEQ128R2)&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;The Role&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;As a Specialist Solutions Architect (SSA) – Data Engineering, you are a hands-on technical authority who guides strategic customers in designing, building, and optimizing production-grade data workloads on the Databricks Data Intelligence Platform. Partnering closely with Account Teams and Solution Architects, you translate complex big data challenges into high-performance, scalable architectures using Apache Spark™ and modern streaming frameworks.&amp;nbsp;&lt;br&gt;&lt;br&gt;In this role, you will drive successful implementations, align technical roadmaps to accelerate platform adoption, and establish deep domain specialization; whether in real-time streaming, performance optimization, or operational data layers, while expanding your impact across Field Engineering.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;The impact you will have:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Drive Technical Wins &amp;amp; Scope:&lt;/strong&gt; Lead end-to-end technical design, proof of concepts (PoCs), and workload sizing for strategic customer engagements, acting as a trusted advisor to front-line technical stakeholders to secure technical wins.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Architect Production Data Systems:&lt;/strong&gt; Design, build, and optimize scalable, high-performance batch and streaming pipelines, operational data layers (Lakebase), and end-to-end performance load testing on Databricks.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Deploy Interactive Data Applications:&lt;/strong&gt; Build and operationalize custom user-facing data applications using Databricks Apps, transforming data pipelines and AI models into interactive tools.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI-Native Engineering:&lt;/strong&gt; Leverage AI coding assistants, LLMs, and agentic workflows (e.g., Genie Code, Cursor) as a force multiplier to rapidly prototype, debug, and deliver architectural assets with full ownership of outputs.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Enablement &amp;amp; Domain Leadership:&lt;/strong&gt; Mentor peers, contribute reusable architecture assets, and deliver technical workshops and community presentations to scale expertise across accounts and field teams.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What we look for:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Deep Data Engineering Expertise:&lt;/strong&gt; 5+ years in data or software engineering with hands-on proficiency in distributed processing (Apache Spark™, Delta Lake, SDP) and real-time streaming technologies (Spark Streaming, Kafka, CDC).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI-First Builder Mindset:&lt;/strong&gt; Demonstrated daily reliance on AI coding tools and LLMs to accelerate pipeline development, troubleshooting, and asset generation.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Production Programming &amp;amp; Foundations:&lt;/strong&gt; Strong production coding skills in Python, SQL, and Scala or Java, with a solid grasp of data modeling and system design fundamentals.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Customer Advisory &amp;amp; Delivery:&lt;/strong&gt; 5+ years in pre-sales or post-sales technical consulting, managing customer engagements and navigating multi-stakeholder technical discussions.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Operational &amp;amp; HTAP Architectures:&lt;/strong&gt; Practical experience with operational/transactional data layers (Postgres/OLTP), low-latency serving, reverse ETL, and hybrid transactional/analytical processing.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Nice to haves:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Cloud &amp;amp; Migration Mastery:&lt;/strong&gt; Hands-on experience with major cloud platforms (AWS, Azure, GCP) and legacy data lake modernisation (e.g., Hadoop migration and cost optimisation).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Application Experience:&lt;/strong&gt; Background in constructing specialised data applications (e.g., risk modelling, fraud detection, customer lifetime value) across industries as a data expert.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Ecosystem &amp;amp; Culture Contribution:&lt;/strong&gt; Active track record of technical community engagement, public speaking, open-source contributions, or peer mentoring and interviewing.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Flexibility &amp;amp; Travel:&lt;/strong&gt; Ability to travel up to 30% for strategic customer engagements and internal alignment.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Notes on the role:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;This will be an office-based contract (Amsterdam), with a hybrid schedule, requiring up to 30% travel when needed for customer visits, events &amp;amp; trainings.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;An initial 12-month fixed-term contract is to be offered, with the expectation of extending/converting to FTE upon successful completion of the probation period.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-hybrid&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Databricks&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;Databricks is the Data and AI company. More than 20,000 organizations worldwide — including adidas, AT&amp;amp;T, Bayer, Block, Mastercard, Rivian, Unilever, and 70% of the Fortune 500 — rely on the Databricks Data + AI Platform to build and scale data and AI apps, analytics and agents. Headquartered in San Francisco with 30+ offices around the globe, Databricks offers a unified platform that includes Genie, Lakebase, Agent Bricks, Lakeflow, Lakehouse, and Unity Catalog. To learn more, follow Databricks on &lt;a href=&quot;https://www.linkedin.com/company/databricks&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://x.com/databricks&quot;&gt;X&lt;/a&gt;, &lt;a href=&quot;https://www.youtube.com/@Databricks&quot;&gt;YouTube&lt;/a&gt;, and &lt;a href=&quot;https://www.instagram.com/databricksinc/?hl=en&quot;&gt;Instagram&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Benefits&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;At Databricks, we strive to provide comprehensive benefits and perks that meet the needs of all of our employees. For specific details on the benefits offered in your region click &lt;a href=&quot;https://docs.google.com/document/d/154un3e8Xav4BceOSlcYFZRGEuQI54xMxVydRwQn54eQ/edit?usp=sharing&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Diversity and Inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Databricks, we are committed to fostering a diverse and inclusive culture where everyone can excel. We take great care to ensure that our hiring practices are inclusive and meet equal employment opportunity standards. Individuals looking for employment at Databricks are considered without regard to age, color, disability, ethnicity, family or marital status, gender identity or expression, language, national origin, physical and mental ability, political affiliation, race, religion, sexual orientation, socio-economic status, veteran status, and other protected characteristics.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Compliance&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If access to export-controlled technology or source code is required for performance of job duties, it is within Employer&#39;s discretion whether to apply for a U.S. government license for such positions, and Employer may decline to proceed with an applicant on this basis alone.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.nl">Jobs in Netherlands</a> on Arbeitnow</a>

&lt;h2&gt;About Nscale&lt;/h2&gt;
&lt;p&gt;Nscale is the GPU cloud engineered for AI. We provide cost-effective, high-performance infrastructure for AI start-ups and large enterprise customers. Nscale enables AI-focused companies to achieve superior results by reducing the complexity of AI development. Our GPU cloud bolsters technical capabilities and directly supports strategic business outcomes, including cost management, rapid innovation, and environmental responsibility.&lt;/p&gt;
&lt;p&gt;We thrive on a culture of relentless innovation, ownership, and accountability, where every team member takes pride in their work and drives it with excellence and urgency. As an Nscaler, you’ll build trust through openness and transparency, where everyone is inspired to do their best work. If you join our team, you’ll be contributing to building the technology that powers the future.&lt;/p&gt;
&lt;h2&gt;About the Role&lt;/h2&gt;
&lt;p&gt;We’re hiring an &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Infrastructure Engineer (OpenStack Ironic Specialist)&lt;/strong&gt;&lt;/strong&gt; to design, operate, and continuously improve the bare metal provisioning platforms that underpin Nscale’s infrastructure.&lt;/p&gt;
&lt;p&gt;This role sits within the &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Infrastructure Engineering team&lt;/strong&gt;&lt;/strong&gt;, which is responsible for the design, implementation, operation, and ongoing improvement of the infrastructure stack supporting both internal and customer-facing services. You’ll work closely with &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;network, compute, data centre, support, and pre-sales teams&lt;/strong&gt;&lt;/strong&gt;, while also serving as a specialist escalation point for advanced provisioning and hardware issues.&lt;/p&gt;
&lt;p&gt;This is a high-impact role focused on &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;OpenStack Ironic&lt;/strong&gt;&lt;/strong&gt;, automated hardware lifecycle management, and the reliable operation of large-scale physical infrastructure. You’ll also help connect Nscale to the broader &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;upstream OpenStack community&lt;/strong&gt;&lt;/strong&gt;, ensuring our bare metal platforms evolve in line with real operational needs and industry direction.&lt;/p&gt;
&lt;h2&gt;What you&#39;ll be doing&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Bare Metal Provisioning &amp;amp; Lifecycle Management&lt;/strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li value=&quot;1&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Design&lt;/strong&gt;&lt;/strong&gt; scalable and resilient bare metal provisioning platforms with a strong focus on &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;OpenStack Ironic&lt;/strong&gt;&lt;/strong&gt;.&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Own&lt;/strong&gt;&lt;/strong&gt; the full lifecycle of physical infrastructure, including discovery, enrolment, provisioning, cleaning, deprovisioning, and hardware state management.&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Build&lt;/strong&gt;&lt;/strong&gt; and maintain provisioning workflows for a wide range of hardware profiles, including &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;GPU-enabled&lt;/strong&gt;&lt;/strong&gt; and high-performance server platforms.&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Support&lt;/strong&gt;&lt;/strong&gt; platform upgrades, lifecycle management, and operational improvements across &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Ironic&lt;/strong&gt;&lt;/strong&gt; and its dependencies.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Automation &amp;amp; Platform Integration&lt;/strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li value=&quot;1&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Manage&lt;/strong&gt;&lt;/strong&gt; and improve integrations between &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Ironic&lt;/strong&gt;&lt;/strong&gt; and related OpenStack services such as &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Nova, Neutron, Glance, Keystone, and Placement&lt;/strong&gt;&lt;/strong&gt;.&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Drive&lt;/strong&gt;&lt;/strong&gt; automation for hardware onboarding, firmware and BIOS configuration, deployment workflows, validation, and recovery.&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Implement&lt;/strong&gt;&lt;/strong&gt; infrastructure automation using &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;infrastructure-as-code&lt;/strong&gt;&lt;/strong&gt; and configuration management approaches.&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Ensure&lt;/strong&gt;&lt;/strong&gt; provisioning platforms and operational processes align with security, compliance, and operational standards.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Troubleshooting, Reliability &amp;amp; Operational Support&lt;/strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li value=&quot;1&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Troubleshoot&lt;/strong&gt;&lt;/strong&gt; complex issues across provisioning pipelines, &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;PXE/iPXE&lt;/strong&gt;&lt;/strong&gt;, BMC interfaces, out-of-band management, image deployment, network boot, and hardware compatibility.&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Act&lt;/strong&gt;&lt;/strong&gt; as a &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;3rd/4th line escalation point&lt;/strong&gt;&lt;/strong&gt; for advanced bare metal and provisioning incidents.&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Perform&lt;/strong&gt;&lt;/strong&gt; root cause analysis and implement long-term fixes to improve platform reliability and repeatability.&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Participate&lt;/strong&gt;&lt;/strong&gt; in on-call rotations and incident response activities for critical infrastructure services.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Cross-Functional Collaboration &amp;amp; Community Engagement&lt;/strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li value=&quot;1&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Collaborate&lt;/strong&gt;&lt;/strong&gt; with network, compute, data centre, and support teams to deliver reliable physical infrastructure services.&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Contribute&lt;/strong&gt;&lt;/strong&gt; specialist input to infrastructure roadmap planning, capacity expansion, standard builds, and hardware platform qualification.&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Support&lt;/strong&gt;&lt;/strong&gt; pre-sales and solution design efforts with expert guidance on bare metal capabilities, operational models, and deployment constraints.&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Contribute&lt;/strong&gt;&lt;/strong&gt; to upstream OpenStack bare metal communities through bug reports, testing, reviews, design discussions, and code contributions where appropriate.&lt;/li&gt;
&lt;li value=&quot;5&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Track&lt;/strong&gt;&lt;/strong&gt; upstream roadmaps and release changes to help shape Nscale’s bare metal strategy, upgrade planning, and platform standards.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;KPIs&lt;/h2&gt;
&lt;ul&gt;
&lt;li value=&quot;1&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Automated provisioning and hardware onboarding reliability&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Bare metal incident resolution and root cause closure&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Platform upgrade and lifecycle delivery across Ironic dependencies&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Upstream OpenStack Ironic community contribution and adoption alignment&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;About You&lt;/h2&gt;
&lt;ul&gt;
&lt;li value=&quot;1&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Strong experience&lt;/strong&gt;&lt;/strong&gt; operating Linux systems and troubleshooting production infrastructure&lt;/li&gt;
&lt;li value=&quot;2&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Strong specialist knowledge&lt;/strong&gt;&lt;/strong&gt; of &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;OpenStack Ironic&lt;/strong&gt;&lt;/strong&gt; and the surrounding provisioning ecosystem&lt;/li&gt;
&lt;li value=&quot;3&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Strong understanding&lt;/strong&gt;&lt;/strong&gt; of bare metal provisioning concepts including &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;PXE/iPXE, DHCP, TFTP/HTTP boot, BMC technologies, RAID configuration, firmware management, disk imaging, and node lifecycle states&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;4&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Strong experience&lt;/strong&gt;&lt;/strong&gt; with out-of-band management technologies such as &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Redfish, IPMI, or vendor management interfaces&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;5&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Strong experience&lt;/strong&gt;&lt;/strong&gt; designing and building automation for physical and virtual infrastructure using tools such as &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Ansible&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;6&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Strong scripting skills&lt;/strong&gt;&lt;/strong&gt; in &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Python and Bash&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li value=&quot;7&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Experience&lt;/strong&gt;&lt;/strong&gt; troubleshooting complex provisioning and hardware integration issues across server, network, and management layers&lt;/li&gt;
&lt;li value=&quot;8&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Experience&lt;/strong&gt;&lt;/strong&gt; operating infrastructure at scale with a focus on reliability, repeatability, and operational safety&lt;/li&gt;
&lt;li value=&quot;9&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Ability&lt;/strong&gt;&lt;/strong&gt; to collaborate across infrastructure, support, and architecture teams to solve complex technical problems&lt;/li&gt;
&lt;li value=&quot;10&quot;&gt;&lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;Experience&lt;/strong&gt;&lt;/strong&gt; contributing to or working closely with upstream open-source communities, particularly &lt;strong&gt;&lt;strong class=&quot;textBold&quot;&gt;OpenStack, Ironic, Metal3, or related infrastructure projects&lt;/strong&gt;&lt;/strong&gt;, is highly desirable&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;What we can offer you&lt;/h2&gt;
&lt;p&gt;At Nscale, you&#39;ll find a collaborative, supportive, and innovative environment where your contributions spark real impact. We&#39;re building something extraordinary, and we want you at the core.&lt;/p&gt;
&lt;p&gt;Highly competitive US compensation package (base + bonus + equity), with performance reviews every 12 months. 🚀&lt;/p&gt;
&lt;p&gt;Join one of the fastest-growing AI infrastructure companies — your chance to directly shape how global AI capacity is planned and deployed. ✨&lt;/p&gt;
&lt;p&gt;Expect a dynamic progression plan tailored to your ambitions. Grow by leading critical cross-functional initiatives and shaping capital strategy — always with our full support.&lt;/p&gt;
&lt;p&gt;Human-First Flexibility: We treat you as humans first. 🫶🏽 Our flexible workplace trusts Nscalers to deliver, giving you the autonomy to shape your day around life&#39;s moments.&lt;/p&gt;
&lt;h2&gt;Equal Opportunities Statement&lt;/h2&gt;
&lt;p&gt;We strongly encourage applications from people of colour, the LGBTQ+ community, people with disabilities, neurodivergent people, parents, carers, and people from lower socio-economic backgrounds.&lt;/p&gt;
&lt;p&gt;If there’s anything we can do to accommodate your specific situation, please let us know.&lt;/p&gt;
&lt;p&gt;The responsibilities outlined in this job description are not exhaustive and are intended to provide a general overview of the position. The employee may be required to perform additional duties, tasks, and responsibilities as assigned by management, consistent with the skills and qualifications required for the role.&lt;/p&gt;
&lt;p&gt;For information on how Nscale handles candidate personal data, please see our Employee &amp;amp; Candidate Privacy Notice: Here.&lt;/p&gt;
&lt;p&gt;For information on how Nscale handles candidate personal data, please see our Employee &amp;amp; Candidate Privacy Notice: Here.&lt;/p&gt;
&lt;h2&gt;Salary Range&lt;/h2&gt;
&lt;p&gt;The range below reflects the base salary for the position. Actual compensation may vary based on job-related factors such as skill set, experience, education, and location. In addition to base salary, this role may be eligible for bonus, equity, and/or commission programs. Nscale may offer a competitive benefits package including medical, dental, vision, flexible paid time off, parental leave, and retirement plan participation.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;For information on how Nscale handles candidate personal data, please see our Employee &amp;amp; Candidate Privacy Notice:&amp;nbsp;&lt;a href=&quot;https://drive.google.com/file/d/1QK5Yg04WHD9K9IAtJgQWubJZC9oLvatK/view?usp=sharing&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://drive.google.com/file/d/1QK5Yg04WHD9K9IAtJgQWubJZC9oLvatK/view?usp%3Dsharing&amp;amp;source=gmail&amp;amp;ust=1765375172804000&amp;amp;usg=AOvVaw2Ncte4rmlGl8OKuFuDgDtx&quot;&gt;Here.&lt;/a&gt;&lt;br&gt;&lt;br&gt;Nscale does not accept unsolicited candidate submissions from recruitment agencies.&lt;br&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.nl">Jobs in Netherlands</a> on Arbeitnow</a>

&lt;h2&gt;&lt;strong&gt;About Nscale&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Nscale is the GPU cloud engineered for AI. We provide cost-effective, high-performance infrastructure for AI start-ups and large enterprise customers. Nscale enables AI-focused companies to achieve superior results by reducing the complexity of AI development. Our GPU cloud bolsters technical capabilities and directly supports strategic business outcomes, including cost management, rapid innovation, and environmental responsibility.&lt;/p&gt;
&lt;p&gt;We thrive on a culture of relentless innovation, ownership, and accountability, where every team member takes pride in their work and drives it with excellence and urgency. As an Nscaler, you&#39;ll build trust through openness and transparency, where everyone is inspired to do their best work. If you join our team, you&#39;ll be contributing to building the technology that powers the future.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;We&#39;re seeking a Director of Technical Program Management – Networking to build and lead the team of Technical Program Managers who deliver Nscale&#39;s network infrastructure across Europe. This team sits within our Deployment organisation, a build org that owns every step from hardware arrival on site through to customer acceptance.&lt;/p&gt;
&lt;p&gt;You&#39;ll own the delivery of cluster networking, data centre networking, and WAN programmes across our European sites, leading TPMs who partner with Network Engineering, Data Centre Operations, Supply Chain, and external carriers and vendors. This is a hands-on leadership role for someone who has delivered networks at hyperscale and knows how to turn complex, multi-site builds into predictable, repeatable execution. The role involves regular travel to our sites and partners.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;What You&#39;ll be Doing&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Build, lead, and mentor a team of Technical Program Managers covering cluster networking, data centre networking, and WAN delivery across Europe.&lt;/li&gt;
&lt;li&gt;Own the end-to-end network delivery plan for new GPU cluster builds and expansions, from hardware arrival through installation, validation, and customer acceptance.&lt;/li&gt;
&lt;li&gt;Set the operating model for network programme delivery: planning standards, milestone gates, risk and dependency management, and reporting.&lt;/li&gt;
&lt;li&gt;Partner with Network Engineering on design readiness, BOMs, and build sequencing for Ethernet and InfiniBand fabrics, front-end networks, and WAN interconnects.&lt;/li&gt;
&lt;li&gt;Drive alignment across Deployment, Data Centre Operations, Supply Chain, Procurement, SRE, and Commercial teams so network delivery never blocks customer handover.&lt;/li&gt;
&lt;li&gt;Manage strategic relationships with carriers, IXPs, colocation providers, and network hardware vendors.&lt;/li&gt;
&lt;li&gt;Establish metrics for delivery speed, quality, and predictability, and use them to drive continuous improvement.&lt;/li&gt;
&lt;li&gt;Communicate status, risks, and trade-offs clearly to executive leadership and customers.&lt;/li&gt;
&lt;li&gt;Hire top TPM talent in a highly competitive market and grow a high-performing, accountable team culture.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;About You&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;12+ years of experience in technical programme management, network engineering, or infrastructure delivery, including 5+ years leading TPM or engineering teams.&lt;/li&gt;
&lt;li&gt;Track record delivering large-scale network infrastructure at a hyperscaler or major network vendor (e.g. Microsoft, AWS, Oracle/OCI, Cisco, or similar).&lt;/li&gt;
&lt;li&gt;Strong technical grounding in cluster and data centre networking, WAN, and routing (BGP, EVPN/VXLAN, Ethernet and InfiniBand fabrics).&lt;/li&gt;
&lt;li&gt;Experience running multi-site, multi-country builds with complex hardware, vendor, and carrier dependencies.&lt;/li&gt;
&lt;li&gt;Proven ability to build programme management frameworks that scale with a fast-growing organisation.&lt;/li&gt;
&lt;li&gt;Excellent executive communication and stakeholder management skills; comfortable influencing without authority.&lt;/li&gt;
&lt;li&gt;Willingness to travel regularly across Europe to sites and partners.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Nice to Have&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Experience delivering networking for large GPU clusters or AI training environments.&lt;/li&gt;
&lt;li&gt;Familiarity with HPC network topologies (Fat Tree, Rail) and high-speed optics (400G/800G).&lt;/li&gt;
&lt;li&gt;Experience with network automation and infrastructure-as-code in a deployment context.&lt;/li&gt;
&lt;li&gt;PMP, PgMP, or similar certification.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Why this role matters&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Every GPU we deploy is only as useful as the network that connects it. This role sets how quickly and reliably Nscale turns hardware into capacity our customers can use, and shapes how network delivery scales as we expand across Europe.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Equal Opportunities Statement&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;At Nscale, we are committed to fostering an inclusive, diverse, and equitable workplace. We believe that a variety of perspectives enriches our work environment, and we encourage applications from candidates of all backgrounds, experiences, and abilities. We strongly encourage applications from people of colour, the LGBTQ+ community, people with disabilities, neurodivergent people, parents, carers, and people from lower socio-economic backgrounds.&lt;/p&gt;
&lt;p&gt;If there&#39;s anything we can do to accommodate your specific situation, please let us know.&lt;/p&gt;
&lt;p&gt;The responsibilities outlined in this job description are not exhaustive and are intended to provide a general overview of the position. The employee may be required to perform additional duties, tasks, and responsibilities as assigned by management, consistent with the skills and qualifications required for the role.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;For information on how Nscale handles candidate personal data, please see our Employee &amp;amp; Candidate Privacy Notice:&amp;nbsp;&lt;a href=&quot;https://drive.google.com/file/d/1QK5Yg04WHD9K9IAtJgQWubJZC9oLvatK/view?usp=sharing&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://drive.google.com/file/d/1QK5Yg04WHD9K9IAtJgQWubJZC9oLvatK/view?usp%3Dsharing&amp;amp;source=gmail&amp;amp;ust=1765375172804000&amp;amp;usg=AOvVaw2Ncte4rmlGl8OKuFuDgDtx&quot;&gt;Here.&lt;/a&gt;&lt;br&gt;&lt;br&gt;Nscale does not accept unsolicited candidate submissions from recruitment agencies.&lt;br&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.nl/english-speaking-jobs">English Speaking Jobs in Netherlands</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;strong&gt;Who we are&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;Samsara (NYSE: IOT) is the pioneer of the Connected Operations™ Cloud, which is a platform that enables organizations that depend on physical operations to harness Internet of Things (IoT) data to develop actionable insights and improve their operations. At Samsara, we are helping improve the safety, efficiency and sustainability of the physical operations that power our global economy. Representing more than 40% of global GDP, these industries are the infrastructure of our planet, including agriculture, construction, field services, transportation, and manufacturing — and we are excited to help digitally transform their operations at scale.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;Working at Samsara means you’ll help define the future of physical operations and be on a team that’s shaping an exciting array of product solutions, including Video-Based Safety, Vehicle Telematics, Apps and Driver Workflows, and Equipment Monitoring. As part of a recently public company, you’ll have the autonomy and support to make an impact as we build for the long term.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a member of our Security Operations Team, you will collaborate with a global team of engineers to monitor and respond to security events, lead security incidents as Incident Commander, and lead digital forensic investigations in support of Employee Relations, Legal, Compliance, or Information Security cases.&lt;/p&gt;
&lt;p&gt;Although you will be focused on security incident response, you will also have the opportunity to create and maintain runbooks, and automated workflows, and assist in process refinement and implementation. You will collaborate with a diverse team of engineers, and key stakeholders on security initiatives across the company. Above all, your focus is bringing Security expertise to the table in a collaborative, humble, and practical manner.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location:&lt;/strong&gt; This role is open to candidates residing in Netherlands&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You should apply if:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;You want to impact the industries that run our world:&lt;/strong&gt; Every phone call you answer and every email you send can affect whether truck drivers deliver goods on time and without accidents, whether students get dropped off safely from school, or whether power gets restored quickly after a natural disaster.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You thrive the most when solving problems:&lt;/strong&gt; Our constantly expanding technology and the complexities faced by our customers provide an exciting range of challenges for our Customer Success teams. With a growth mindset and a desire to learn, you will strategically partner with our customers to find unique solutions to help keep their operations safe, efficient, and sustainable.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You are a natural relationship builder:&lt;/strong&gt; Whether the relationship is with our customers or with cross-functional teams in Samsara, you are in constant communication and collaboration with key stakeholders to win as a team.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You are the architect of your own career:&lt;/strong&gt; If you put in the work, this role won’t be your last at Samsara. This Customer Success team is still shaping its future and you will have plenty of autonomy and opportunities to master your craft in a hyper growth environment.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You want to be with the best: &lt;/strong&gt;At Samsara, we win together, celebrate together and support each other. You will be surrounded by the best and brightest professionals out there.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;In this role, you will:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Monitor security events and provide technical analysis on alerts&lt;/li&gt;
&lt;li&gt;Lead information security incidents and employee insider investigations by developing the incident response strategy, lead the execution through incident closure, while providing incident updates to key stakeholders throughout the incident&lt;/li&gt;
&lt;li&gt;Deliver security guidance clearly and concisely for incident response and insider threat initiatives&lt;/li&gt;
&lt;li&gt;Coordinate the building of services, capabilities, integrations, and implementations of technologies to support security operations, incident response, and insider threat&lt;/li&gt;
&lt;li&gt;Champion, role model, and embed Samsara’s cultural principles (Focus on Customer Success, Build for the Long Term, Adopt a Growth Mindset, Be Inclusive, Win as a Team) as we scale globally and across new offices&lt;/li&gt;
&lt;li&gt;Participate in our on-call rota covering weekends&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Minimum requirements for the role:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of experience in Security Incident Response&lt;/li&gt;
&lt;li&gt;Ability to communicate investigative findings and strategies to technical staff, executive leadership, and legal&lt;/li&gt;
&lt;li&gt;Ability to build scripts or tools to support Samsara’s investigation processes, with proficiency in Python&lt;/li&gt;
&lt;li&gt;Mentor and train security operation engineers on data collection, analysis, and reporting technical analysis&lt;/li&gt;
&lt;li&gt;Practical experience acting as a lead during security incident response, including monitoring and triaging alerts, and coordinating across teams&lt;/li&gt;
&lt;li&gt;Understanding of analysis and forensics techniques on macOS, Windows, and Linux&lt;/li&gt;
&lt;li&gt;Experience utilizing SIEM tools to perform log reviews&lt;/li&gt;
&lt;li&gt;Experience in cloud architecture and security (AWS, GCP) and cloud-based services&lt;/li&gt;
&lt;li&gt;Participation in an on-call rotation, with the potential to work outside standard business hours, including late evenings, when responding to high-severity incidents as part of our global incident response team.&lt;/li&gt;
&lt;li&gt;This role will be part of our EMEA so your hours will be aligned to the UK. As an operational time you may be expected to work flexible hours around this to support the load of the team&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;An ideal candidate also has:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;2+ years of experience working on insider threat initiatives or employee investigations&lt;/li&gt;
&lt;li&gt;Bachelor’s or Master’s degree in Computer Science, Information Security, or a related field - or relevant industry experience&lt;/li&gt;
&lt;li&gt;GIAC Certified Incident Handler (GCIH) or similar Certification&lt;/li&gt;
&lt;li&gt;Familiarity with common security frameworks and standards, including NIST Cybersecurity Framework, ISO 27001, FedRAMP&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Total Rewards&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Samsara, we build for the people who keep the global economy moving. We want owners, not passengers, which is why &lt;a href=&quot;https://www.samsara.com/company/careers/benefits&quot;&gt;our rewards&lt;/a&gt; are designed to fuel high-impact builders. Our compensation program delivers above-market total compensation through a combination of base salary, performance-based bonus/variable pay, and equity (for eligible roles) in a high-growth public company. We meaningfully differentiate pay for our top performers, who have the opportunity to earn above-market compensation that can outpace the broader market over time.&lt;/p&gt;
&lt;p&gt;Beyond compensation, we provide the foundations that enable long-term success: a flexible, employee-led remote model, a professional development stipend, comprehensive health and parental leave plans, and more. If you’re ready to build for the long term and own the outcome, your journey starts here.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Flexible Working&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Samsara, we embrace a flexible working model that caters to the diverse needs of our teams. Our offices are open for those who prefer to work in-person and we also support remote work where it aligns with our operational requirements. For certain positions, being close to one of our offices or within a specific geographic area is important to facilitate collaboration, access to resources, or alignment with our service regions. In these cases, the job description will clearly indicate any working location requirements. Our goal is to ensure that all members of our team can contribute effectively, whether they are working on-site, in a hybrid model, or fully remotely. All offers of employment are contingent upon an individual’s ability to secure and maintain the legal right to work at the company and in the specified work location, if applicable.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Belonging at Samsara&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Samsara, we welcome everyone regardless of their background. All qualified applicants will receive consideration for employment without regard to race, color, religion, national origin, sex, gender, gender identity, sexual orientation, protected veteran status, disability, age, and other characteristics protected by law. We depend on the unique approaches of our team members to help us solve complex problems and want to ensure that Samsara is a place where people from all backgrounds can make an impact.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Accommodations&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Samsara is an inclusive work environment, and we are committed to ensuring equal opportunity in employment for qualified persons with disabilities. Please email &lt;a ---------- or &lt;a href=&quot;https://forms.gle/DrM6DFQUiSgfPtCVA&quot;&gt;click here&lt;/a&gt; if you require any reasonable accommodations throughout the recruiting process.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Authenticity&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We use &lt;a href=&quot;https://hiretofu.com/privacyPolicy&quot;&gt;Tofu&lt;/a&gt;, a fraud detection tool, to validate the authenticity of applications and protect against identity fraud. This ensures we are connecting with real people and allows us to prioritize genuine candidates. Please see Samsara’s &lt;a href=&quot;https://www.samsara.com/legal/candidate-privacy-notice&quot;&gt;Candidate Privacy Notice&lt;/a&gt; for more information.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Fraudulent Employment Offers&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Samsara is aware of scams involving fake job interviews and offers. Please know we do not charge fees to applicants at any stage of the hiring process. Official communication about your application will only come from emails ending in ----- ----- or ----- For more information regarding fraudulent employment offers, please visit our&amp;nbsp;&lt;a href=&quot;https://samsara.com/blog/avoiding-fake-job-offers&quot;&gt;blog post here&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.nl/english-speaking-jobs">English Speaking Jobs in Netherlands</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Welcome to Planet. We believe in using space to help life on Earth.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Planet designs, builds, and operates the largest constellation of imaging satellites in history. This constellation delivers an unprecedented dataset of empirical information via a revolutionary cloud-based platform to authoritative figures in commercial, environmental, and humanitarian sectors. We are both a space company and data company all rolled into one.&lt;/p&gt;
&lt;p&gt;Customers and users across the globe use Planet&#39;s data to develop new technologies, drive revenue, power research, and solve our world’s toughest obstacles.&lt;/p&gt;
&lt;p&gt;As we control every component of hardware design, manufacturing, data processing, and software engineering, our office is a truly inspiring mix of experts from a variety of domains.&lt;/p&gt;
&lt;p&gt;We have a people-centric approach toward culture and community and we strive to iterate in a way that puts our team members first and prepares our company for growth. Join Planet and be a part of our mission to change the way people see the world.&lt;/p&gt;
&lt;p&gt;Planet is a global company with employees working remotely world wide and joining us from offices in San Francisco, Washington DC, Germany, Austria, Slovenia, and The Netherlands.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the Role:&amp;nbsp;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The design team at Planet is looking for a Senior Product Designer to shape Planet&#39;s platform experience (insights.planet.com - free trial available). In this role, you will be responsible for defining the core user journeys across our platform, addressing the needs of different user types (from admins, to developers, to end users). With a relentless focus on those users, you will define jobs-to-be-done and design end-to-end user flows across web frontends and agentic workflows. You will collaborate closely with Product and Engineering to decompose these workflows into scalable, reusable UX building blocks, ultimately crafting a cohesive, user-centric platform experience.&lt;/p&gt;
&lt;p&gt;The perfect candidate brings a track record of designing sophisticated, data-heavy geospatial applications. This role is full stack, in the design sense: you take a problem from discovery with users all the way to designing and building the interfaces, side by side with our engineers.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This is a full-time, hybrid role which will require you to work from our Berlin or Haarlem office 3 days per week.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Impact You’ll Own:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Product Design Ownership: Lead the end-to-end process from discovery and prototyping to high-fidelity design.&lt;/li&gt;
&lt;li&gt;Geospatial Interface Design: Create intuitive, powerful geospatial interfaces that translate complex data into actionable insights.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;User Research: Gather feedback and conduct user interviews in close collaboration with product partners.&lt;/li&gt;
&lt;li&gt;UI Architecture: Define and architect the interaction patterns and design system for Planet’s platform.&lt;/li&gt;
&lt;li&gt;Cross-functional Collaboration: Partner with product and engineering to ensure top-tier design quality.&lt;/li&gt;
&lt;li&gt;Culture: Help build and elevate Planet&#39;s design culture.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What You Bring:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;6+ years designing complex digital products, with a track record of shipping technical, SaaS, or B2B software end to end.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Bachelor’s degree in design or an equivalent field.&lt;/li&gt;
&lt;li&gt;A portfolio with geospatial or data analytics work: interactive maps, layered geospatial data and time series (time sliders, change over time, comparisons), plus the statistics and charts that turn data into an insight.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Solid core craft in UX/UI, interaction design, prototyping, accessibility, and visual design, plus Figma and enterprise design systems.&lt;/li&gt;
&lt;li&gt;An AI-native way of working. You can prototype in code with AI coding assistants, and you&#39;re comfortable with Git and merge requests.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Research you run yourself: user interviews and usability testing, synthesized into clear product direction.&lt;/li&gt;
&lt;li&gt;Comfort with ambiguity. You take vague, complex problems and drive them to a validated solution without daily oversight.&lt;/li&gt;
&lt;li&gt;A dynamic, iterative, low-ego way of working with PMs, engineers, and other designers.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What Makes You Stand Out:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience designing for developers, data scientists, or AI agents.&lt;/li&gt;
&lt;li&gt;Hands-on with remote sensing analysis and familiarity with geospatial standards.&lt;/li&gt;
&lt;li&gt;You enjoy meeting customers and are open to travel within Europe.&lt;/li&gt;
&lt;li&gt;Experience helping a team adopt new ways of working.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Application Deadline:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;11:45p / 23:45 CET on the date stated below. Applications are reviewed on a rolling basis. This posting may be removed earlier than projected if a suitable pool of applications has been received. For this reason, we recommend applying as soon as you are able to.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefits While Working at Planet:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;These offerings are dependent on employment type and geographical location, based upon applicable law or company policy.&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Paid time off including vacation, holidays and company-wide days off&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Employee Wellness Program&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Home Office Reimbursement&lt;/li&gt;
&lt;li&gt;Monthly Phone and Internet Reimbursement&lt;/li&gt;
&lt;li&gt;Tuition Reimbursement and access to LinkedIn Learning&lt;/li&gt;
&lt;li&gt;Equity&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Volunteering Paid Time Off&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The expected starting gross salary range for this role is listed below. Individual placement within this range is determined objectively based on gender-neutral criteria such as your skills, qualifications, and professional experience. This position may also be eligible for discretionary bonuses and/or equity.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Netherlands Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;€66.600&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;€83.300 EUR&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;San Francisco Fair Chance Ordinance&lt;br&gt;&lt;/strong&gt;Pursuant to the San Francisco Fair Chance Ordinance, we will consider for employment qualified applicants with arrest and conviction records.&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Why we care so much about Belonging.&amp;nbsp;&lt;br&gt;&lt;/strong&gt;We’re dedicated to helping the whole Planet, and to do that we must strive to represent all of it within each of our offices and on all of our teams. That’s why Planet is guided by an ultimate north star of Belonging—dreaming big as we approach our ongoing work.&amp;nbsp; If this job intrigues you, but you’re thinking you might not have all the qualifications, please... do apply!&amp;nbsp; At Planet, we are looking for well-rounded people from around the world who can contribute to more ways than just what is listed in this job description.&amp;nbsp; We don’t just fill positions, we aspire to fulfill people’s careers, most excited about folks who are motivated by our underlying humanitarian efforts.&amp;nbsp; We are a few orbits around the sun before we get to where we want to be, so we hope you’re excited to come along for the ride.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;EEO statement: &lt;br&gt;&lt;/strong&gt;Planet is committed to building a community where everyone belongs and we invite people from all backgrounds to apply. Planet is an equal opportunity employer, and committed to providing employment opportunities regardless of race, religious creed, color, national origin, ancestry, physical disability, mental disability, medical condition, genetic information, marital status, sex, gender, gender identity, gender expression, pregnancy, childbirth and breastfeeding, age, sexual orientation, military or veteran status, or any other protected classification, in accordance with applicable federal, state, and local laws. &lt;a href=&quot;https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12.pdf&quot;&gt;Know Your Rights.&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Accommodations:&amp;nbsp;&lt;br&gt;&lt;/strong&gt;Planet is an inclusive community and we know that everyone has their own needs. If you have a disability or special need that requires accommodation during the hiring process, please reach out to ----- or contact your recruiter with your request. Your message will be confidential and we will be happy to assist you.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Privacy Policy&lt;/strong&gt;: By clicking &quot;Apply Now&quot; at the top of this job posting, I acknowledge that I have read the &lt;a href=&quot;https://www.planet.com/privacy/#california&quot;&gt;Planet Data Privacy Notice for California Staff Members and Applicants&lt;/a&gt;, and hereby consent to the collection, processing, use, and storage of my personal information as described therein.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Privacy Policy (European Applicants):&lt;/strong&gt; By clicking &quot;Apply Now&quot; at the top of this job posting, I acknowledge that I have read the &lt;a href=&quot;https://www.planet.com/privacy/&quot;&gt;Candidate Privacy Notice GDPR Planet Labs Europe&lt;/a&gt;, and hereby consent to the collection, processing, use, and storage of my personal information as described therein.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;AI in Our Interviewing Process&lt;/strong&gt;: Planet is committed to providing an exceptional interview experience for all candidates. We currently use &lt;a href=&quot;https://www.metaview.ai/&quot; target=&quot;_blank&quot;&gt;Metaview&lt;/a&gt; to better focus on candidates and less on trying to capture notes. As such, with the candidate&#39;s consent, select interviews may be recorded and include a &quot;Planet AI Notetaker&quot; for transcription and summarization purposes. Should an interview involve use of AI interview technologies, the candidate will receive notification and have the ability to opt out both in advance and/or real-time. Opting out will not affect one&#39;s candidacy.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Candidate AI Policy&lt;/strong&gt;: Planet embraces Artificial Intelligence (AI) tools, and we encourage its responsible use. We understand that candidates may use various resources, including AI tools, to &lt;em&gt;prepare&lt;/em&gt; for interviews and assessments. However, &lt;em&gt;during any live interview stage or when actively completing assessments for this position, the use of AI tools—e.g. Large Language Models (LLMs), deep fake technology, etc.—is strictly prohibited unless explicitly prompted by an interviewer or assessment instructions&lt;/em&gt;. If you are unsure about acceptable use, please contact your recruiter for clarification. If an AI tool or similar technology is desired as an accommodation, please contact ----- with your request for assistance. Your message will be confidential, and we will be happy to assist you. Violation of this policy may result in disqualification of your application.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.nl">Jobs in Netherlands</a> on Arbeitnow</a>

&lt;h1&gt;In a nutshell&amp;nbsp;&lt;/h1&gt;
&lt;p&gt;Picnic is building a new generation of intelligent shopping experiences and fulfillment automation with AI. In our app, we help customers search in their own words, plan meals around their household and shop effortlessly. In our supply chain, automation helps us deliver efficiently and sustainably.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;As an AI Platform Engineer, you’ll build the tools and infrastructure to take AI from experiment to dependable production system: model access, tracing, evaluation, fine-tuning and low-latency serving. You&#39;ll set the technical direction for how engineers build with AI, working closely with product teams across search, personalisation, and fulfillment automation.&lt;/p&gt;
&lt;h1&gt;Tricks of the trade&lt;/h1&gt;
&lt;p&gt;&lt;strong&gt;Provide an environment in which agents run at optimal cost: &lt;/strong&gt;Evolve our AI Gateway with provider integrations, model routing, fallbacks, rate limits, privacy controls, and cost attribution.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Standardise LLM tracing, evals and benchmarking:&lt;/strong&gt; Build end-to-end tracing, evaluation, and production monitoring across prompts, models, retrieval, tools, and agent state. Help teams turn human judgement and customer outcomes into repeatable evaluation sets.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Productionize open-weight models:&lt;/strong&gt; Create the path to fine-tune, evaluate and serve open-weight models. Support real-time inference and high-throughput batch workloads, and make latency, performance and cost trade-offs visible.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Build a paved path for getting agents to run in production:&lt;/strong&gt; Enable developers by providing clear APIs, SDKs, templates and local tooling for structured generation, tool use, model experiments and agent workflows. Make the supported path easier than assembling one-off infrastructure.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Tech: &lt;/strong&gt;You’ll work with Python on a daily basis, using frameworks like FastAPI, LiteLLM, OpenAI, Gemini and more. Supporting this core stack are Snowflake, PostgreSQL, OpenSearch, RabbitMQ, Kafka, Git, Docker, Kubernetes, AWS, Helm, Terraform, Vault, and Datadog. Our open-weight training and serving stack is one of the choices you&#39;ll help us make.&lt;/p&gt;
&lt;h1&gt;We’re looking for&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s degree or higher in Computer Science, AI or a related field&lt;/li&gt;
&lt;li&gt;Strong backend engineering fundamentals, especially in Python&lt;/li&gt;
&lt;li&gt;Proven track record building self-service AI platforms and scaling their adoption&lt;/li&gt;
&lt;li&gt;Experience bringing language models or other ML/AI systems into production with meaningful reliability, latency, security, and cost requirements&lt;/li&gt;
&lt;li&gt;Familiarity with cloud infrastructure, containers, Kubernetes, CI/CD and observability&lt;/li&gt;
&lt;li&gt;Able to take end-to-end ownership, make pragmatic build-versus-buy decisions and work effectively across platform, ML/AI and product teams&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;+ Bonus points!&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience with LLM or agent gateways, tool protocols such as MCP, guardrails or policy-aware model access&lt;/li&gt;
&lt;li&gt;Experience with LLM fine-tuning and serving&lt;/li&gt;
&lt;/ul&gt;
&lt;h1&gt;Picnic Perks&amp;nbsp;&lt;/h1&gt;
&lt;p&gt;&lt;strong&gt;🫱🏼‍🫲🏾 Teamwork makes the dream work&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;With more than 80 nationalities across 3 countries, you’ll be part of a diverse company with plenty of cool stuff to get involved with, from board game evenings to after-work drinks to our company ski trip and more!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;💡 Make a difference&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You’ll work in an awesome startup environment with the freedom to drive your own projects and create a visible impact. Our fully electric vehicles and sustainable business model mean you’ll also be contributing to making the world a better place!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🥗 Fresh Lunch, coffee, and snacks&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our offices are equipped with fully-fledged coffee bars and a kitchen and chefs. They prepare delicious fresh and warm lunches every day so you can keep your energy up.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🚲 Health insurance discount &amp;amp; bike plan&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We have a partnership with CZ (a health insurance provider). Picnic employees get a discount on CZ insurance packages between 5% and 15%. Furthermore, through our partnership with Lease a Bike, you can rent-to-own a new (e)bike at a discounted rate&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🌎 Relocation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;If you’re moving from another country to join Picnic we make it as smooth as possible for you. We’ll cover your flight costs for you and your partner and kids, your first month&#39;s rent and moving costs (up to €2000), and help you with the 30% tax ruling setup and application.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;📆 All the rest&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Picnic you get 25 holidays, we cover your travel expenses and offer a pension plan. And your phone and laptop are on us, as well.&amp;nbsp;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.nl/english-speaking-jobs">English Speaking Jobs in Netherlands</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Every day, tens of millions of people come to Roblox to explore, create, play, learn, and connect with friends in 3D immersive digital experiences– all created by our global community of developers and creators.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Roblox, we’re building the tools and platform that empower our community to bring any experience that they can imagine to life. Our vision is to reimagine the way people come together, from anywhere in the world, and on any device.&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re on a mission to connect a billion people with optimism and civility, and looking for amazing talent to help us get there.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;A career at Roblox means you’ll be working to shape the future of human interaction, solving unique technical challenges at scale, and helping to create safer, more civil shared experiences for everyone.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;As&amp;nbsp;&lt;strong&gt;Director, Developer Relations – &lt;/strong&gt;Europe, you will lead Roblox’s developer ecosystem strategy and growth across Europe. You will be accountable for defining the regional strategy, establishing the partnerships and programs required to execute it, and delivering measurable outcomes for the Roblox developer ecosystem.&lt;/p&gt;
&lt;p&gt;You will build deep relationships with leading developers, studios, publishers, technology partners, and emerging creators while identifying the next generation of high-potential partners for Roblox. You will serve as a senior representative of Roblox within the regional games and technology industries and as an executive-level advocate for the needs and opportunities of developers within Roblox.&lt;/p&gt;
&lt;p&gt;This role requires both strategic vision and operational leadership. You will translate Roblox’s global priorities into a regional strategy, identify opportunities and barriers to ecosystem growth, and mobilize teams across Product, Engineering, Marketing, Partnerships, Creator, and International to deliver against those opportunities.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;You Have&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;10+ years of experience in developer relations, games, partnerships, platform strategy, or related fields.&lt;/li&gt;
&lt;li&gt;Experienced leading regional or ecosystem strategy with measurable business impact.&lt;/li&gt;
&lt;li&gt;Deeply knowledgeable about the games and developer landscape in Europe.&lt;/li&gt;
&lt;li&gt;Able to influence senior internal and external stakeholders.&lt;/li&gt;
&lt;li&gt;Data-driven, strategic, and comfortable operating in ambiguity.&lt;/li&gt;
&lt;li&gt;Familiar with Roblox Studio, Unity, Unreal, or similar development tools.&lt;/li&gt;
&lt;li&gt;Based in the Netherlands or willing to relocate.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;You Will&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Own the multi-year developer ecosystem strategy for Europe.&lt;/li&gt;
&lt;li&gt;Drive developer acquisition, engagement, and long-term success.&lt;/li&gt;
&lt;li&gt;Build executive relationships with key studios, publishers, and ecosystem partners.&lt;/li&gt;
&lt;li&gt;Identify regional developer needs and influence Roblox product priorities.&lt;/li&gt;
&lt;li&gt;Set goals, metrics, and operating rhythms for regional ecosystem growth.&lt;/li&gt;
&lt;li&gt;Partner cross-functionally to turn strategy into execution.&lt;/li&gt;
&lt;li&gt;Represent Roblox at major industry and developer events.&lt;/li&gt;
&lt;li&gt;Surface market trends, opportunities, and risks to senior leadership.&lt;/li&gt;
&lt;li&gt;Build and lead the regional Developer Relations organization as the opportunity grows.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;What Success Looks Like&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Success in this role means that Roblox has a clear and durable developer ecosystem strategy for Europe, stronger relationships with the region’s most important developers and studios, a growing pipeline of high-potential developers building on Roblox, and a measurable increase in the quality and success of experiences emerging from the region.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Roles that are based in an office are onsite Tuesday, Wednesday, and Thursday, with optional presence on Monday and Friday (unless otherwise noted).&lt;/p&gt;
&lt;p&gt;Roblox provides equal employment opportunities to all employees and applicants for employment and prohibits discrimination and harassment of any type without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other characteristic protected by federal, state or local laws. Roblox also provides reasonable accommodations to candidates with qualifying disabilities or religious beliefs during the recruiting process.&lt;/p&gt;
&lt;p&gt;For US based roles only, please note the Company may not be able to employ candidates for this role who have United States work authorization related to certain U.S. visa categories, or support future H-1B sponsorship at this time.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.nl">Jobs in Netherlands</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;At Stark, we forge the future of European and national security through cutting-edge, AI-driven technology and unmatched engineering precision. As a premier defence technology company, our mission is clear: to equip NATO Allies and their partners &amp;nbsp;with next-generation autonomous defence platforms and advanced AI-driven software built to perform in the world’s most demanding environments.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;We believe that true security stems from relentless innovation. By combining elite engineering talent with agile technology and an AI-native operational culture, Stark turns complex defence challenges into field-tested, multi-domain solutions.&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Why Join Us?&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;The software and systems you work on directly protect personnel and defend European and national sovereignty.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;You will work alongside industry-leading minds on autonomous systems, advanced propulsion, and secure cyber platforms.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;We foster a fast-paced, collaborative environment where bold ideas are supported by serious R&amp;amp;D backing.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;p&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Your Mission&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;As a Cloud Engineer (All genders), you will focus on transforming service requests into production-ready, scalable environments. By utilizing Infrastructure as Code (IaC), you ensure every deployment is executed with precision, security, and thorough documentation.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Your work will directly impact the reliability and scalability of our embedded autonomy infrastructure deployed across air, land, and sea systems.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;WHAT YOU WILL DO AT STARK&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Act as the primary contact for infrastructure service requests.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Build and maintain Terraform modules to ensure consistent state management and streamlined deployments.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Configure and install services with a strong emphasis on security protocols.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Monitor cloud provider activities to ensure cost-efficiency and compliance with security standards.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Produce detailed &quot;How-to&quot; guides for new services to enable developer self-service.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;WHAT YOU BRING TO THE MISSION&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;2 to 4 years of professional Cloud Engineering experience.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Strong practical knowledge of GCP is preferred; AWS or Azure experts willing to transition are welcome. Experience with hybrid or on-prem systems is a plus.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Advanced proficiency in Terraform.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Skilled in Kubernetes (k8s / GKE) and GitOps frameworks like Flux or Kustomize.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;A commitment to supporting technical teams through well-architected infrastructure.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Equal Opportunity:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;At Stark Defence, we are committed to building a diverse, inclusive, and high-performing team. We operate in an industry where women, as well as other minority groups, are systematically under-represented. We actively encourage applications from candidates of all backgrounds and identities.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;If you are excited about this role, we encourage you to apply even if you don&#39;t meet all the listed qualifications—ability and impact cannot be summarised in a few bullet points. We value unique perspectives, adaptability, and a drive to solve high-stakes challenges.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Security Clearance:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Due to the nature of our work in the defence sector, candidates must be eligible to obtain and maintain the appropriate security clearance required for this position. Details will be provided during the recruitment process.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.com">Jobs in Germany</a> on Arbeitnow</a>

